SELECT extensions.is(internal.parse_initial_media_source_candidate(item->>'canonical'),item->'candidate','accept '||(item->>'name'))
 FROM source_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.is(internal.initial_preparation_digest('preparation-candidate',item->>'canonical'),item->>'digest','digest '||(item->>'name'))
 FROM source_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_media_source_candidate(%L)',internal.initial_canonical(
 jsonb_set(v#>ARRAY['valid',item->>'base','candidate'], ARRAY(SELECT jsonb_array_elements_text(item->'path')),item->'value'))),
 '22023','initial_analysis_input_invalid','reject '||(item->>'name'))
 FROM source_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'invalid') item;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_media_source_candidate(%L)',(item->>'canonical')||E'\n'),
 '22023','initial_analysis_input_invalid','reject noncanonical '||(item->>'name'))
 FROM source_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.ok(NOT has_function_privilege(role_name,signature,'EXECUTE'),'no API parser grant '||role_name||signature)
 FROM unnest(ARRAY['anon','authenticated','service_role']) role_name CROSS JOIN unnest(ARRAY[
 'internal.initial_media_source_candidate_schema_v2()','internal.initial_media_source_semantics(jsonb)','internal.parse_initial_media_source_candidate(text)']) signature;
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation remains false');
-- The later dormant allocator recognizes the shape but still requires a real
-- owner before any global claim. Parsing cannot fabricate one. Whole-cohort
-- empty-catalog and closed-gate behavior is in initial_media_source_lifecycle.sql.
SELECT set_config('request.jwt.claim.role','service_role',TRUE);
UPDATE internal.initial_analysis_rollout SET initial_analysis_lifecycle_enabled=TRUE;
CREATE TEMP TABLE counts_before AS SELECT
 (SELECT count(*) FROM internal.initial_analysis_operation_fences) fences,
 (SELECT count(*) FROM internal.initial_analysis_preparation_intents) intents,
 (SELECT count(*) FROM internal.ai_quota_reservations) funding,
 (SELECT count(*) FROM internal.initial_analysis_media_registry) objects;
SELECT extensions.throws_ok(format('SELECT public.create_initial_preparation_intent(%L,%L,%L)',
 '00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-00000000f101',item->>'canonical'),
 'P0002','initial_analysis_owner_unavailable','media allocation cannot fabricate owner '||(item->>'name'))
 FROM source_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_input(%L)',item->>'canonical'),
 '22023','initial_analysis_input_invalid','source plan cannot become admitted input '||(item->>'name'))
 FROM source_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') item;
SELECT extensions.is((SELECT count(*) FROM internal.initial_analysis_operation_fences),fences,'no global claim') FROM counts_before;
SELECT extensions.is((SELECT count(*) FROM internal.initial_analysis_preparation_intents),intents,'no intent') FROM counts_before;
SELECT extensions.is((SELECT count(*) FROM internal.ai_quota_reservations),funding,'no funding') FROM counts_before;
SELECT extensions.is((SELECT count(*) FROM internal.initial_analysis_media_registry),objects,'no storage') FROM counts_before;
SELECT * FROM extensions.finish();
ROLLBACK;
